## What's going on

The drift comes from `convertBetweenCurrenciesWithBankerRounding` being called **twice** for payouts that were partially reversed. The second call rounds an amount that is already in minor units, so every JPY → EUR payout drifts by up to ¥1 (≈ €0.006) per reversal line. 💸

Relevant file: /private/tmp/newjen-worst/Developer/clients/northwind-industries-holdings/platform-monorepo/services/billing-reconciliation/src/modules/ledger/reconciliation/adapters/stripe/handlers/payout-failed-with-partial-reversal.handler.ts

| Currency | Payouts | Drift (minor units) |
|---|---|---|
| JPY → EUR | 1,284 | 1,031 |
| KRW → USD | 312 | 290 |
| EUR → EUR | 9,876 | 0 |

Here is the corrected conversion (unchanged lines included so you can compare):

```ts
import { Money, CurrencyCode, MinorUnits } from "@northwind/shared/money";
import { getExponent } from "@northwind/shared/money/iso-4217";

/**
 * Converts an amount between currencies using banker's rounding (round half to even).
 * Must be called exactly once per ledger line: the input is in MINOR units of `from`.
 */
export function convertBetweenCurrenciesWithBankerRounding(
  amount: MinorUnits,
  from: CurrencyCode,
  to: CurrencyCode,
  rate: number,
): MinorUnits {
  if (from === to) {
    return amount;
  }
  const fromExponent = getExponent(from); // JPY = 0, EUR = 2, KWD = 3
  const toExponent = getExponent(to);
  const major = amount / 10 ** fromExponent;
  const converted = major * rate * 10 ** toExponent;
  return roundHalfToEven(converted) as MinorUnits;
}

function roundHalfToEven(value: number): number {
  const floor = Math.floor(value);
  const diff = value - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

export function reconcileCurrency(lines: ReadonlyArray<LedgerLine>, rates: RateTable): ReconciledLine[] {
  return lines.map((line) => {
    const rate = rates.lookup(line.currency, line.settlementCurrency, line.settledAt);
    const settled = convertBetweenCurrenciesWithBankerRounding(line.amount, line.currency, line.settlementCurrency, rate);
    return {
      ...line,
      settledAmount: settled,
      driftMinorUnits: settled - line.expectedSettledAmount,
      reconciliationStatus: settled === line.expectedSettledAmount ? "matched" : "drifted",
    };
  });
}
```

